# Initialize an empty to-do list
to_do_list = []

def add_item():
    """Add a new item to the to-do list."""
    item = input("Enter a new item to add (or type 'done' to complete the current item): ")

    if item.lower() == "done":
        # If the user types 'done', remove the last item from the list
        if to_do_list:
            to_do_list.pop()
            print("Current To-Do List:", to_do_list)
        else:
            print("Your to-do list is empty.")
    else:
        # Add the new item to the to-do list
        to_do_list.append(item)
        print("Current To-Do List:", to_do_list)

def remove_item():
    """Remove the last item from the to-do list."""
    if to_do_list:
        to_do_list.pop()
        print("Current To-Do List:", to_do_list)
    else:
        print("Your to-do list is empty.")

def view_items():
    """Print the current to-do list."""
    print("Current To-Do List:", to_do_list)

# Main loop
while True:
    print("\nAvailable actions:")
    print("1. Add an item")
    print("2. Remove an item")
    print("3. View items")
    print("4. Exit")

    action = input("Enter the number of the action you want to perform: ")

    if action == "1":
        add_item()
